const inventoryUsed=()=>Number((S?.inventory||[]).filter(x=>Number(x.qty||0)>0).length);
const inventoryTotal=()=>Number((S?.inventory||[]).reduce((a,x)=>a+Math.max(0,Number(x.qty||0)),0));
