const jobProgress=j=>{const a=new Date(j?.started_at||0).getTime(),b=new Date(j?.finish_at||0).getTime(),n=Date.now();if(!a||!b||b<=a)return 0;return Math.max(0,Math.min(100,(n-a)/(b-a)*100))};
