async function currentSession(){const {data,error}=await sb.auth.getSession();if(error)throw error;session=data.session;return session}
async function api(action,payload={}){const s=await currentSession();if(!s)throw new Error('unauthorized');const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','apikey':PUB,'Authorization':'Bearer '+s.access_token},body:JSON.stringify({action,...payload})});const d=await r.json().catch(()=>({error:'bad_response'}));if(!r.ok)throw new Error(d.error||'server_error');if(d.state)S=d.state;return d}
async function registerAccount(username,password){const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','apikey':PUB},body:JSON.stringify({action:'register',username,password})});const d=await r.json().catch(()=>({error:'bad_response'}));if(!r.ok)throw new Error(d.error||'register_failed');return d}
async function loginAccount(username,password){const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','apikey':PUB},body:JSON.stringify({action:'login',username,password})});const d=await r.json().catch(()=>({error:'bad_response'}));if(!r.ok)throw new Error(d.error||'invalid_credentials');return d}
async function applySession(authSession){if(!authSession?.access_token||!authSession?.refresh_token)throw new Error('invalid_credentials');const {data,error}=await sb.auth.setSession({access_token:authSession.access_token,refresh_token:authSession.refresh_token});if(error||!data.session)throw new Error('invalid_credentials');session=data.session}

function closeModal(immediate=false){const m=$('#modal');if(!m)return;clearTimeout(modalCloseTimer);watchingExpeditionId=null;partyPick=[];partySite=null;if(immediate){m.classList.add('hidden');m.classList.remove('open','closing');m.innerHTML='';return}m.classList.remove('open');m.classList.add('closing');modalCloseTimer=setTimeout(()=>{m.classList.add('hidden');m.classList.remove('closing');m.innerHTML=''},180)}
function modal(html,extra=''){const m=$('#modal');clearTimeout(modalCloseTimer);m.classList.remove('hidden','closing','open');m.innerHTML=`<div class="sheet ${extra}">${html}</div>`;requestAnimationFrame(()=>m.classList.add('open'))}
function showAuth(){closeModal(true);S=null;session=null;$('#app').classList.add('hidden');$('#authGate').classList.remove('hidden');authMsg('')}
async function enterGame(){const s=await currentSession();if(!s){showAuth();return}$('#authGate').classList.add('hidden');$('#app').classList.remove('hidden');try{await api('state');render()}catch(e){if(e.message==='unauthorized'){await sb.auth.signOut();showAuth()}else{toast('서버 상태를 불러오지 못했습니다.')}}}

function companyRank(){const fame=Number(S?.player?.fame||0);if(fame>=3000)return ['재앙급 법인','S'];if(fame>=1500)return ['대형 박멸사','A'];if(fame>=600)return ['전문 박멸사','B'];if(fame>=150)return ['지역 업체','C'];return ['신생 용역사','D']}
function candidateText(){if(!S?.player?.next_candidate_at)return '-';const d=Math.max(0,new Date(S.player.next_candidate_at).getTime()-Date.now());if(!d)return S.candidates?.length?'면접 대기':'곧 도착';const h=Math.floor(d/3600000),m=Math.floor((d%3600000)/60000);return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`}
function briefText(){const active=(S?.expeditions||[]).filter(e=>e.active).length,pending=totalPending();if(pending)return `화물 ${pending}개 수령 대기`;if(active)return `작전 ${active}건 진행 중`;if((S?.candidates||[]).length)return `지원자 ${(S.candidates||[]).length}명 대기`;return `다음 지원자 ${candidateText()}`}

function drawMonster(c,m,x=32,y=40,scale=1,phase=0){if(!c||!m)return;const g=c.getContext('2d');g.save();g.clearRect(0,0,c.width,c.height);g.imageSmoothingEnabled=false;g.translate(x,y+Math.sin(phase)*1.5);g.scale(scale,scale);const body=m.family==='slime'?'#73b77b':m.family==='goblin'?'#9eb25e':'#7e9071';const dark=m.family==='slime'?'#3d6c49':m.family==='goblin'?'#586733':'#465446';g.fillStyle='#0c0e0c';g.fillRect(-14,16,28,5);if(m.family==='slime'){g.fillStyle=dark;g.fillRect(-12,-2,24,20);g.fillRect(-8,-9,16,8);g.fillRect(-15,7,4,8);g.fillRect(11,7,4,8);g.fillStyle=body;g.fillRect(-10,-4,20,18);g.fillRect(-6,-10,12,7)}else if(m.family==='goblin'){g.fillStyle=body;g.fillRect(-10,-7,20,22);g.fillRect(-15,-5,6,7);g.fillRect(9,-5,6,7);g.fillStyle=dark;g.fillRect(-7,15,5,8);g.fillRect(3,15,5,8);g.fillStyle='#6e4c2d';g.fillRect(12,2,5,22);g.fillRect(8,2,12,4)}else{g.fillStyle=body;g.fillRect(-13,-9,26,25);g.fillRect(-18,-3,6,18);g.fillRect(12,-3,6,18);g.fillStyle=dark;g.fillRect(-9,16,7,9);g.fillRect(3,16,7,9);g.fillStyle='#5c4531';g.fillRect(-6,-15,12,7)}g.fillStyle='#e5dfc4';g.fillRect(-6,-3,4,4);g.fillRect(3,-3,4,4);g.fillStyle='#161816';g.fillRect(-5,-2,2,2);g.fillRect(4,-2,2,2);g.fillStyle='#b46d38';g.fillRect(-5,7,10,3);g.restore()}
function drawEnemy(g,x,y,phase){g.save();g.translate(x,y+Math.sin(phase+.8)*1.2);g.fillStyle='#1a1714';g.fillRect(-11,14,22,4);g.fillStyle='#d1b08d';g.fillRect(-7,-9,14,12);g.fillStyle='#725642';g.fillRect(-9,-14,18,6);g.fillStyle='#6c7480';g.fillRect(-10,3,20,16);g.fillStyle='#beb7a6';g.fillRect(7,1,4,22);g.fillStyle='#d5d0c4';g.fillRect(4,-3,10,4);g.restore()}
function battleCanvas(canvas,e){if(!canvas||!e||!S)return;const m=S.monsters.find(x=>x.id===e.monster_id),site=S.sites.find(x=>x.id===e.site_id);if(!m||!site)return;const g=canvas.getContext('2d'),w=canvas.width,h=canvas.height,t=Date.now()/180;g.clearRect(0,0,w,h);g.imageSmoothingEnabled=false;const cycle=(t%16);const attacking=cycle>5&&cycle<9;const mx=76+(attacking?Math.min(22,(cycle-5)*8):0),ex=w-82-(attacking?0:Math.max(0,Math.sin(t*.7)*3));drawMonster(canvas,m,mx,h-58,1.3,t*.7);drawEnemy(g,ex,h-50,t*.8);if(attacking){g.fillStyle='#f0b65c';g.fillRect(mx+34,h-80,26,5);g.fillRect(mx+49,h-89,5,20);if(cycle>7){g.fillStyle='#d75d52';g.fillRect(ex-18,h-88,8,8);g.fillRect(ex+12,h-96,6,6)}}g.fillStyle='#0009';g.fillRect(8,8,130,18);g.fillStyle='#e8ece6';g.font='10px monospace';g.fillText(`${m.name} · Lv.${m.level}`,14,20);g.fillStyle='#0009';g.fillRect(w-150,8,142,18);g.fillStyle='#e8ece6';g.fillText((e.battle_state?.enemy||site.enemy_names?.[0]||'용사'),w-143,20)}

function hq(){const active=(S.expeditions||[]).filter(e=>e.active),pending=totalPending(),cap=capacity(),used=inventoryUsed(),craftJobs=activeCraftJobs(),sellJobs=activeSellJobs();return `
<section class="facility-stack">
  <button class="facility-row dorm" data-action="dorm"><img src="assets/icon-dorm.svg" alt=""><span class="facility-copy"><b>숙소</b><small>${S.monsters.length}/${cap} 몬스터</small></span><span class="facility-side"><em>Lv.${S.player.quarters_level}</em><i>›</i></span></button>
  <button class="facility-row recruit" data-action="candidates"><img src="assets/icon-recruit.svg" alt=""><span class="facility-copy"><b>영입소</b><small>3시간마다 ${recruitBatch()}명 · 현재 ${(S.candidates||[]).length}명</small></span><span class="facility-side"><em>Lv.${S.player.tavern_level}</em><i>›</i></span></button>
  <button class="facility-row workshop" data-action="workshop"><img src="assets/icon-workshop.svg" alt=""><span class="facility-copy"><b>제작소</b><small>작업 ${craftJobs.length}/${S.craftCapacity||5} · 총 대기열 ${S.craftCapacity||5}</small></span><span class="facility-side"><em>Lv.${S.player.workshop_level||1}</em><i>›</i></span></button>
  <button class="facility-row shop" data-action="shop"><img src="assets/icon-shop.svg" alt=""><span class="facility-copy"><b>상점</b><small>판매 ${sellJobs.length}/${S.shopCapacity||5} · 총 대기열 ${S.shopCapacity||5}</small></span><span class="facility-side"><em>Lv.${S.player.shop_level||1}</em><i>›</i></span></button>
  <button class="facility-row storage" data-action="warehouse"><img src="assets/icon-storage.svg" alt=""><span class="facility-copy"><b>전리품 창고</b><small>${fmt(inventoryTotal())}개 보관 · ${inventoryUsed()}종</small></span><span class="facility-side"><em>Lv.${S.player.storage_level||1}</em><i>›</i></span></button>
</section>
${active.length?`<section class="home-live"><header><b>진행 중인 작전</b><small>${active.length}건</small></header>${active.slice(0,3).map(e=>{const site=S.sites.find(x=>x.id===e.site_id),p=partyOf(e);return `<button data-action="watch" data-id="${e.id}"><span class="live-pin"></span><span><b>${esc(site?.name||'작전')}</b><small>${esc(partyLabel(e))} · ${p.length}인 · 승리 ${fmt(e.kills)} · 화물 ${lootCount(e)}</small></span><i>관전</i></button>`}).join('')}</section>`:''}`}


function dormModal(){const cap=capacity();modal(`<div class="sheet-head lodge-head"><div><div class="section-kicker">MONSTER QUARTERS</div><h2>숙소 인원 관리</h2><p>${S.monsters.length}/${cap}명 입실 · 숙소 Lv.${S.player.quarters_level}</p></div><button class="close-btn" data-action="close">×</button></div><div class="lodge-list">${S.monsters.map(m=>{const e=activeOf(m.id);return `<button class="lodge-row" data-action="employee" data-id="${m.id}"><span class="lodge-avatar">${charSvg(monsterAsset(m.family),'lodge-sprite '+formClass(m))}</span><span class="lodge-info"><b>${esc(m.name)}</b><small>${formName(m)} · 성장 ${esc(m.growth_grade||'C')} · ${esc(m.trait||'무특성')}</small><em class="${e?'field':''}">${e?'현장 출동':'숙소 대기'}</em></span><span class="lodge-stats"><i><small>LV</small><b>${m.level}</b></i><i><small>전투</small><b>${fmt(power(m))}</b></i><i><small>재능</small><b>${fmt(m.talent)}</b></i></span></button>`}).join('')}</div><div class="lodge-footer"><span><small>다음 정원</small><b>${cap} → ${cap+2}명</b></span><button class="primary-btn" data-action="upgrade" data-id="quarters">숙소 확장 · ${fmt(nextQuarterCost())}G</button></div>`,`lodge-sheet`)}

function monsters(){return `
<div class="page-head"><div><span>MONSTER ROSTER</span><h2>몬스터 리스트</h2></div><button class="primary-btn" data-action="candidates">영입 ${(S.candidates||[]).length}</button></div>
<section class="personnel-list">${S.monsters.map(m=>{const e=activeOf(m.id);return `<button class="personnel-row ${e?'deployed':''}" data-action="employee" data-id="${m.id}"><span class="personnel-avatar">${charSvg(monsterAsset(m.family),'employee-sprite '+formClass(m))}</span><span class="personnel-info"><b>${esc(m.name)}</b><small>${formName(m)} · ${esc(m.trait||'무특성')}</small><em>${e?'현장 출동':'본부 대기'}</em></span><span class="personnel-power"><small>전투력</small><b>${fmt(power(m))}</b><i>LV.${m.level}</i></span></button>`}).join('')}</section>`}

function hunt(){const active=(S.expeditions||[]).filter(e=>e.active);return `
<div class="compact-head"><div><b>박멸 작전</b><small>${active.length}개 파티 출동 중 · 몬스터별 자유 파견</small></div></div>
<section class="mission-list compact-missions">${S.sites.map(site=>{const ex=activeAt(site.id),unlocked=!!site.unlocked,pending=sitePending(site.id),collectable=siteHasCollectable(site.id),wins=Number(site.progress?.normal_wins||0),bossReady=!!site.progress?.boss_ready,bossCleared=!!site.progress?.boss_cleared,pct=bossCleared?100:Math.min(100,wins/500*100),party=ex[0]?partyOf(ex[0]):[],drops=(site.loot||[]).length;return `<article class="mission-card compact-mission ${unlocked?'':'locked'}" data-action="mission" data-id="${site.id}" data-site="${site.id}"><div class="mission-art"></div><div class="mission-wash"></div><div class="mission-file"><header><div><div class="mission-code">${siteCode(site.id)}</div><div class="mission-title">${esc(site.name)}${bossReady?'<span class="boss-flag">BOSS</span>':bossCleared?'<span class="boss-flag cleared">CLEAR</span>':''}</div></div><span class="risk">권장 ${fmt(site.recommended_power)}</span></header><div class="mission-middle"><div class="squad">${party.length?party.slice(0,4).map(mm=>`<span class="party-avatar">${charSvg(monsterAsset(mm.family),'party-sprite '+formClass(mm))}</span>`).join(''):'<span class="empty-slot">+</span>'}</div></div><footer class="mission-foot"><div><div class="op-state">${ex.length?`${esc(ex[0]?.phase||'탐색')} · ${party.length}인 · 화물 ${pending}`:(unlocked?(bossReady?'보스 출현':bossCleared?`보스 격파 · 드롭 ${drops}종`:`파티 배치 가능 · 드롭 ${drops}종`):'이전 보스 처치 필요')}</div><div class="stage-progress"><span><i style="width:${pct}%"></i></span><small>${bossCleared?'완료':bossReady?'500/500':`${Math.min(500,wins)}/500`}</small></div></div><div class="mission-cta"><button class="chapter-loot-btn" data-action="collect-site" data-site="${site.id}" ${collectable?'':'disabled'}>전리품 수거 <strong>(${fmt(pending)}/3000)</strong></button></div></footer></div></article>`}).join('')}</section>`}


function loot(){const groups=(S.expeditions||[]).filter(e=>lootCount(e)>0),total=totalPending(),used=inventoryUsed(),cap=Number(S.storageCapacity||40),pct=Math.min(100,used/cap*100);return `
<div class="compact-head"><div><b>전리품 창고</b><small>보관 ${used}/${cap} · 수령 대기 ${total}</small></div><button class="soft-btn" data-action="upgrade" data-id="storage">창고 Lv.${S.player.storage_level||1} · ${fmt(facilityCost('storage'))}G</button></div>
<div class="storage-meter"><div><i style="width:${pct}%"></i></div><span>${Math.round(pct)}%</span></div>
<div style="display:flex;justify-content:flex-end;margin-bottom:6px"><button class="primary-btn" data-action="collect-all" ${total?'':'disabled'}>전체 수령</button></div>
${groups.length?groups.map(e=>{const site=S.sites.find(x=>x.id===e.site_id);return `<section class="warehouse-group compact-warehouse"><header><span><b>${esc(site?.name||'현장')}</b><small>${esc(partyLabel(e))} · ${lootCount(e)}개 · ${esc(e.phase||'탐색')}</small></span><button class="soft-btn" data-action="collect-one" data-id="${e.id}">수령</button></header><div class="shelf">${Object.entries(e.pending_loot||{}).map(([name,qty])=>`<div class="item-bin compact-item"><div class="item-art">${itemSvg(itemAsset(name))}</div><b>${esc(name)}</b><strong>${fmt(qty)}</strong></div>`).join('')}</div></section>`}).join(''):`<div class="empty-state warehouse-empty"><div>${itemSvg('crate')}</div><b>대기 화물 없음</b></div>`}
<section class="inventory-card"><div class="compact-head inner"><b>보관 재고</b><small>재료 → 제작소 / 장비 → 몬스터</small></div><div class="inventory-grid">${(S.inventory||[]).length?S.inventory.map(x=>{const d=itemDef(x.item_id),r=recipeForOutput(x.item_id);return `<button class="inventory-slot ${d?.slot?'equippable '+rarityClass(d.rarity):r?'crafted':''}" data-action="item" data-id="${esc(x.item_id)}"><div class="item-art small">${itemSvg(itemAsset(x.item_id))}</div><b>${esc(x.item_id)}</b><small>${fmt(x.qty)}${d?.slot?' · '+slotName(d.slot):r?' · 판매품':''}</small></button>`}).join(''):'<div class="empty-state" style="grid-column:1/-1">비어 있음</div>'}</div></section>`}

function economyJobRows(jobs,type){return jobs.length?`<div class="job-list">${jobs.map((j,i)=>{const waiting=new Date(j.started_at).getTime()>Date.now(),pct=jobProgress(j),qty=Number(type==='craft'?j.batch_qty:j.quantity||1);return `<div class="job-row craft-job ${waiting?'queued':''}" data-progress-start="${esc(j.started_at)}" data-progress-end="${esc(j.finish_at)}"><div class="job-copy"><b>${esc(type==='craft'?j.output_item:j.item_id)} × ${fmt(qty)} ${waiting?'대기':'진행 중'}</b><small>${waiting?`대기열 ${i}`:`<span class="job-percent">${Math.floor(pct)}%</span>`}</small><div class="craft-progress"><i class="craft-progress-fill" style="width:${waiting?0:pct}%"></i></div></div><strong class="job-left">${waiting?'대기 '+leftText(j.started_at):leftText(j.finish_at)}</strong></div>`}).join('')}</div>`:''}

function workshopModal(){const lv=Number(S.player.workshop_level||1),jobs=activeCraftJobs(),cap=Number(S.craftCapacity||lv),queueFull=jobs.length>=cap;modal(`<div class="sheet-head"><div><div class="section-kicker">WORKSHOP</div><h2>제작소</h2><p>한 품목을 원하는 수량만큼 묶어서 순차 생산합니다.</p></div><button class="close-btn" data-action="close">×</button></div><div class="facility-upgrade"><span><small>제작소 Lv.${lv}</small><b>총 대기열 ${cap}개 · 현재 작업 포함</b></span><button class="soft-btn" data-action="upgrade" data-id="workshop">확장 ${fmt(facilityCost('workshop'))}G</button></div><div class="economy-note">모든 제작법은 처음부터 사용 가능 · 제작시간은 <b>1개 기준 시간 × 수량</b> · 제작소 레벨은 제작법이 아니라 <b>총 대기열 수</b>를 늘립니다.</div>${economyJobRows(jobs,'craft')}<div class="recipe-list">${(S.recipes||[]).map(r=>{const inputs=Object.entries(r.inputs||{}),max=craftMaxQty(r),disabled=max<1||queueFull;return `<div class="recipe-row"><div class="recipe-icon">${itemSvg(itemAsset(r.output_item))}</div><div class="recipe-main"><b>${esc(r.output_item)}</b><div class="recipe-meta"><span>판매 <strong>${fmt(r.sale_gold)}G</strong></span><span>1개 제작 ${secText(r.craft_seconds)}</span><span>1개 판매 ${secText(Math.ceil(Number(r.craft_seconds||1)/1.2))}</span></div><div class="recipe-inputs">${inputs.map(([id,q])=>`<span class="${inventoryQty(id)<Number(q)?'short':''}">${esc(id)} ${fmt(inventoryQty(id))} / 개당 ${fmt(q)}</span>`).join('')}</div></div><button class="primary-btn" data-action="craft-setup" data-id="${r.id}" ${disabled?'disabled':''}>${queueFull?'대기열':'제작'}</button></div>`}).join('')}</div>`,'economy-sheet');updateEconomyProgress()}

function craftQuantityModal(recipeId){const r=(S.recipes||[]).find(x=>x.id===recipeId);if(!r)return;const max=craftMaxQty(r);if(max<1){toast('제작 재료가 부족합니다.');return}modal(`<div class="sheet-head"><div><div class="section-kicker">BATCH PRODUCTION</div><h2>${esc(r.output_item)} 제작</h2><p>1 ~ ${fmt(max)}개 중 생산 수량을 선택하세요.</p></div><button class="close-btn" data-action="close">×</button></div><div class="batch-picker"><div class="batch-hero">${itemSvg(itemAsset(r.output_item))}<span><small>선택 수량</small><b id="qtyValue">1개</b></span></div><input id="qtySlider" type="range" min="1" max="${max}" value="1" data-mode="craft" data-id="${r.id}"><div class="slider-scale"><span>1</span><span>최대 ${fmt(max)}</span></div><div id="qtySummary" class="batch-summary"></div><div class="qty-step"><button class="soft-btn" data-action="qty-dec">−</button><button class="soft-btn" data-action="qty-inc">＋</button></div><button class="primary-btn batch-confirm" data-action="craft-confirm" data-id="${r.id}">제작 대기열에 추가</button></div>`,'economy-sheet');updateQuantitySheet()}

function shopModal(){const lv=Number(S.player.shop_level||1),jobs=activeSellJobs(),cap=Number(S.shopCapacity||lv),queueFull=jobs.length>=cap,finished=(S.recipes||[]).map(r=>({...r,qty:inventoryQty(r.output_item),kind:'finished'})).filter(r=>r.qty>0),raw=(S.inventory||[]).map(x=>{const d=rawSaleDef(x.item_id);return d?{id:x.item_id,qty:Number(x.qty||0),sale_gold:Number(d.sale_gold||0),sell_seconds:Number(d.sell_seconds||0),kind:'raw'}:null}).filter(Boolean);const row=r=>{const id=r.output_item||r.id,si=saleInfo(id);return `<div class="shop-item ${r.kind==='raw'?'raw-sale':''}"><div>${itemSvg(itemAsset(id))}</div><div><b>${esc(id)} × ${fmt(r.qty)}</b><small>${r.kind==='raw'?'<em>원재료 직판</em> · ':''}개당 <strong>${fmt(si?.unitGold)}G</strong> · ${secText(si?.unitSeconds)}</small></div><button class="primary-btn" data-action="sell-setup" data-id="${esc(id)}" ${queueFull?'disabled':''}>${queueFull?'대기열':'판매'}</button></div>`};modal(`<div class="sheet-head"><div><div class="section-kicker">COMPANY SHOP</div><h2>상점</h2><p>판매 수량을 묶어서 지정하고 순차 판매합니다.</p></div><button class="close-btn" data-action="close">×</button></div><div class="facility-upgrade"><span><small>상점 Lv.${lv}</small><b>총 대기열 ${cap}개 · 현재 판매 포함</b></span><button class="soft-btn" data-action="upgrade" data-id="shop">확장 ${fmt(facilityCost('shop'))}G</button></div><div class="economy-note">완제품 판매 속도는 동일 품목 제작 속도의 <b>1.2배</b> · 판매시간은 대략 제작시간 ÷ 1.2입니다.</div>${economyJobRows(jobs,'sell')}<div class="shop-section-title"><b>완제품</b><small>가공 후 고수익 판매</small></div><div class="shop-list">${finished.length?finished.map(row).join(''):'<div class="shop-empty">판매 가능한 완제품이 없습니다.</div>'}</div><div class="shop-section-title raw"><b>원재료 직판</b><small>낮은 가격 · 긴급 현금화</small></div><div class="shop-list">${raw.length?raw.map(row).join(''):'<div class="shop-empty">직접 판매할 원재료가 없습니다.</div>'}</div>`,'economy-sheet');updateEconomyProgress()}

function sellQuantityModal(itemId){const si=saleInfo(itemId),max=inventoryQty(itemId);if(!si||max<1)return;modal(`<div class="sheet-head"><div><div class="section-kicker">BATCH SALE</div><h2>${esc(itemId)} 판매</h2><p>1 ~ ${fmt(max)}개 중 판매 수량을 선택하세요.</p></div><button class="close-btn" data-action="close">×</button></div><div class="batch-picker"><div class="batch-hero">${itemSvg(itemAsset(itemId))}<span><small>선택 수량</small><b id="qtyValue">1개</b></span></div><input id="qtySlider" type="range" min="1" max="${max}" value="1" data-mode="sell" data-id="${esc(itemId)}"><div class="slider-scale"><span>1</span><span>최대 ${fmt(max)}</span></div><div id="qtySummary" class="batch-summary"></div><div class="qty-step"><button class="soft-btn" data-action="qty-dec">−</button><button class="soft-btn" data-action="qty-inc">＋</button></div><button class="primary-btn batch-confirm" data-action="sell-confirm" data-id="${esc(itemId)}">판매 대기열에 추가</button></div>`,'economy-sheet');updateQuantitySheet()}

function updateQuantitySheet(){const r=$('#qtySlider'),sum=$('#qtySummary'),val=$('#qtyValue');if(!r||!sum||!val)return;const qty=Math.max(1,Math.min(Number(r.max||1),Number(r.value||1)));r.value=String(qty);val.textContent=`${fmt(qty)}개`;if(r.dataset.mode==='craft'){const x=(S.recipes||[]).find(v=>v.id===r.dataset.id);if(!x)return;sum.innerHTML=`<div><small>총 제작시간</small><b>${secText(Number(x.craft_seconds||0)*qty)}</b></div><div><small>완제품 가치</small><b>${fmt(Number(x.sale_gold||0)*qty)}G</b></div><div class="wide"><small>총 필요 재료</small><p>${Object.entries(x.inputs||{}).map(([id,n])=>`${esc(id)} <b>${fmt(Number(n)*qty)}</b> / 보유 ${fmt(inventoryQty(id))}`).join('<br>')}</p></div>`}else{const si=saleInfo(r.dataset.id);if(!si)return;sum.innerHTML=`<div><small>총 판매시간</small><b>${secText(si.unitSeconds*qty)}</b></div><div><small>총 입금액</small><b>${fmt(si.unitGold*qty)}G</b></div><div class="wide"><small>판매 수량</small><p>${fmt(qty)}개 / 보유 ${fmt(inventoryQty(r.dataset.id))}개</p></div>`}}


function updateChrome(){if(!S)return;const active=(S.expeditions||[]).filter(e=>e.active).length;$('#gold').textContent=fmt(S.player.gold);$('#fame').textContent=fmt(S.player.fame);$('#monsterCount').textContent=fmt(S.monsters.length);$('#activeCount').textContent=fmt(active);$('#pendingCount').textContent=fmt(totalPending());$('#screenTitle').textContent=({home:'본부',monsters:'몬스터',hunt:'작전',loot:'창고'}[screen]||'본부');if($('#briefLine'))$('#briefLine').textContent=briefText();$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.screen===screen))}
function render(){if(!S)return;updateChrome();const v=$('#view'),changed=lastAnimatedScreen!==screen;v.innerHTML=screen==='home'?hq():screen==='monsters'?monsters():screen==='hunt'?hunt():loot();if(changed){v.scrollTop=0;v.classList.remove('view-enter');void v.offsetWidth;v.classList.add('view-enter');lastAnimatedScreen=screen;setTimeout(()=>v.classList.remove('view-enter'),280)}requestAnimationFrame(()=>{paintCanvases();updateEconomyProgress()});updateCandidateTimer()}
function paintCanvases(){syncWatchPanel()}

function updateCandidateTimer(){const e=$('#candidateTimer');if(e)e.textContent=candidateText()}

function candidateModal(){const lv=Number(S.player.tavern_level||1),batch=recruitBatch(),cap=capacity(),room=Math.max(0,cap-S.monsters.length);modal(`<div class="sheet-head"><div><div class="section-kicker">RECRUITING</div><h2>영입소</h2><p>몬스터 영입은 무료입니다. 숙소에 빈자리가 있을 때만 영입할 수 있습니다.</p></div><button class="close-btn" data-action="close">×</button></div><div class="facility-upgrade"><span><small>영입소 Lv.${lv}</small><b>다음 배치 ${batch}명 · 숙소 여유 ${room}/${cap} · A/S급 확률 상승</b></span><button class="soft-btn" data-action="upgrade" data-id="tavern">확장 ${fmt(nextTavernCost())}G</button></div><div class="recruit-free-note"><b>영입 비용 0G</b><span>숙소 정원만 사용합니다.</span></div><div class="candidate-list">${(S.candidates||[]).length?S.candidates.map(c=>`<div class="candidate-card"><div class="candidate-avatar">${charSvg(monsterAsset(c.family),'candidate-sprite')}</div><div><b><span class="candidate-grade ${esc(c.growth_grade||'C')}">${esc(c.growth_grade||'C')}</span>${esc(c.name)} · ${fam(c.family)}</b><small>재능 ${c.talent} · ${esc(c.personality||'침착')} · ${esc(c.trait||'무특성')}</small><span class="candidate-fit">HP ${fmt(c.hp_base)} · 공격 ${fmt(c.atk_base)} · 방어 ${fmt(c.def_base)}</span></div><div class="actions"><button class="primary-btn" data-action="hire" data-id="${c.id}" ${room<1?'disabled':''}>${room<1?'숙소 만원':'무료 영입'}</button><button class="soft-btn" data-action="reject" data-id="${c.id}">거절</button></div></div>`).join(''):`<div class="empty-state">현재 대기 중인 지원자가 없습니다.<br>다음 배치까지 ${candidateText()}</div>`}</div>`,'recruit-sheet') }


function employeeModal(id){const m=S.monsters.find(x=>x.id===id);if(!m)return;const e=activeOf(m.id),site=e&&S.sites.find(x=>x.id===e.site_id),st=monsterStats(m),eq=equippedFor(m.id),sk=skillDef(m),branches=branchesFor(m),ready=readyBranches(m);const gear=['weapon','armor','accessory'].map(slot=>{const row=eq.find(x=>x.slot===slot),d=row&&itemDef(row.item_id);return `<div class="gear-slot ${d?rarityClass(d.rarity):'empty'}"><small>${slotName(slot)}</small>${d?`<b>${itemSvg(itemAsset(d.id))}${esc(d.id)}</b><button data-action="unequip" data-id="${m.id}" data-slot="${slot}">해제</button>`:`<b>비어 있음</b><span>창고 장비를 선택해 장착</span>`}</div>`}).join('');const evo=branches.length?`<section class="evolution-status ${ready.length?'ready':''}"><div><small>${Number(m.evolution_tier||0)+1}차 전직</small><b>${ready.length?`전직 가능 · ${ready.length}개 분기`:`Lv.${branches[0].required_level} 필요 · 현재 Lv.${m.level}`}</b><span>${ready.length?'전직 후 Lv.1부터 새로운 성장 시작':`앞으로 ${Math.max(0,Number(branches[0].required_level)-Number(m.level||0))}레벨`}</span></div><button class="primary-btn" data-action="evolution" data-id="${m.id}" ${!ready.length||e?'disabled':''}>${e?'전투 중':ready.length?'전직 선택':'레벨 부족'}</button></section>`:`<section class="evolution-status final"><div><small>EVOLUTION</small><b>현재 최종 진화체</b><span>추가 전직 경로는 아직 없습니다.</span></div></section>`;modal(`<div class="sheet-head"><div><div class="section-kicker">MONSTER FILE · ${Number(m.evolution_tier||0)?`EVOLUTION ${m.evolution_tier}`:'BASE'} </div><h2>${esc(m.name)}</h2><p>${esc(formName(m))} · ${Number(m.evolution_tier||0)?`${m.evolution_tier}차 전직` : roleOf(m)} · 성장 ${esc(m.growth_grade||'C')}</p></div><button class="close-btn" data-action="close">×</button></div><div class="monster-profile-v10"><div class="monster-identity"><div class="detail-portrait">${charSvg(monsterAsset(m.family),'detail-sprite '+formClass(m))}</div><div><button class="personality-tag" data-action="personality" data-id="${m.id}">${esc(m.personality||'침착')}<i>?</i></button><b>${esc(m.trait||'무특성')}</b><small>Lv.${m.level} · 재능 ${fmt(m.talent)} · 누적 박멸 ${fmt(m.kills)}</small></div></div><div class="combat-stat-grid"><div><small>HP</small><b>${fmt(st.hp)}</b></div><div><small>공격</small><b>${fmt(st.atk)}</b></div><div><small>방어</small><b>${fmt(st.def)}</b></div><div><small>속도</small><b>${fmt(st.spd)}</b></div><div><small>치명</small><b>${Math.round(st.crit*100)}%</b></div><div><small>회피</small><b>${Math.round(st.evade*100)}%</b></div></div>${sk?`<section class="unique-skill-card"><div class="skill-gem">S</div><div><small>고유 스킬</small><b>${esc(sk.name)}</b><strong>${esc(skillTriggerText(sk))}</strong><p>${esc(sk.description||'')}</p></div></section>`:`<section class="unique-skill-card locked"><div class="skill-gem">?</div><div><small>고유 스킬</small><b>전직 후 해금</b><p>Lv.20에 첫 전직을 완료하면 고유 스킬이 생깁니다.</p></div></section>`}${evo}<div class="gear-grid">${gear}</div><div class="detail-note compact"><b>${e?'현장 근무 중':'본부 대기'}</b><br>${e?`${esc(site?.name||'현장')} · 현재 ${esc(e.phase||'탐색')} 단계`:'박멸 화면에서 원하는 던전에 배치할 수 있습니다.'}</div></div>${e?`<div class="battle-actions"><button class="primary-btn" data-action="watch" data-id="${e.id}">현장 보기</button></div>`:''}`,'monster-detail-sheet-v10 evolution-enabled')}

function evolutionModal(id){const m=S.monsters.find(x=>x.id===id);if(!m)return;if(activeOf(m.id)){toast('전투 중에는 전직할 수 없습니다.');return}const branches=branchesFor(m),ready=readyBranches(m);if(!branches.length){toast('현재 최종 진화체입니다.');return}modal(`<div class="sheet-head evolution-head"><div><div class="section-kicker">EVOLUTION BRANCH</div><h2>${esc(m.name)} 전직 선택</h2><p>${esc(formName(m))} Lv.${m.level} → 선택한 진화체 Lv.1</p></div><button class="close-btn" data-action="close">×</button></div><div class="evolution-warning">전직하면 현재 레벨과 XP는 초기화됩니다. 이름·재능·성격·특성·장비·누적 박멸 기록은 유지됩니다.</div><div class="evolution-choice-list">${branches.map(x=>{const sk=(S.skillDefs||[]).find(s=>s.id===x.skill_id),ok=Number(m.level)>=Number(x.required_level);return `<article class="evolution-choice ${ok?'ready':'locked'}"><div class="evolution-preview ${formClass({form_id:x.target_form_id,family:m.family})}">${charSvg(monsterAsset(m.family),'evolution-sprite '+formClass({form_id:x.target_form_id,family:m.family}))}<em>${x.tier}차</em></div><div class="evolution-copy"><header><b>${esc(x.target_name)}</b><span>Lv.${x.required_level}</span></header><p>${esc(x.description||'')}</p><div class="evo-stats"><span>HP ${evoPct(x.hp_mult)}</span><span>공격 ${evoPct(x.atk_mult)}</span><span>방어 ${evoPct(x.def_mult)}</span><span>속도 ${evoPct(x.spd_mult)}</span></div><div class="evo-skill"><small>고유 스킬</small><b>${esc(sk?.name||'-')}</b><strong>${esc(skillTriggerText(sk))}</strong><p>${esc(sk?.description||'')}</p></div></div><button class="primary-btn evolve-select" data-action="evolve-choice" data-id="${m.id}" data-evolution="${x.id}" ${ok?'':'disabled'}>${ok?'이 경로로 전직':`Lv.${x.required_level} 필요`}</button></article>`}).join('')}</div>`,'evolution-sheet')}

function personalityModal(id){const m=S.monsters.find(x=>x.id===id);if(!m)return;const name=m.personality||'침착',meta=personalityMeta(name),night=name==='야행성',active=!night||(kstHour()>=18||kstHour()<6);modal(`<div class="sheet-head"><div><div class="section-kicker">PERSONALITY EFFECT</div><h2>${esc(name)}</h2><p>${esc(m.name)}의 고유 성격 효과</p></div><button class="close-btn" data-action="close">×</button></div><div class="personality-card"><div class="personality-title"><span>${esc(name)}</span>${night?`<em class="${active?'on':'off'}">${active?'야간 효과 활성':'주간 비활성'}</em>`:''}</div><p>${esc(meta.summary)}</p><div class="personality-effects">${meta.effects.map(x=>`<div><b>+</b><span>${esc(x)}</span></div>`).join('')}</div><div class="personality-penalty"><b>주의</b><span>${esc(meta.penalty)}</span></div></div><button class="soft-btn personality-back" data-action="employee" data-id="${m.id}">${esc(m.name)} 상세로 돌아가기</button>`,'personality-sheet')}
function missionModal(siteId,keep=false){const site=S.sites.find(x=>x.id===siteId);if(!site)return;if(!site.unlocked){toast('이전 지역 보스를 먼저 처치해야 합니다.');return}if(!keep||partySite!==siteId){partySite=siteId;partyPick=[]}const ex=activeAt(site.id),progress=site.progress||{};partyPick=partyPick.filter(id=>!activeOf(id));const selected=S.monsters.filter(m=>partyPick.includes(m.id)),sumPower=selected.reduce((a,m)=>a+power(m),0),drops=site.loot||[];const dropRows=drops.map(l=>{const d=itemDef(l.id),eq=d?.kind==='equipment',grade=dropRarity(l.chance),qty=Number(l.min||1)===Number(l.max||1)?`${fmt(l.min||1)}개`:`${fmt(l.min||1)}~${fmt(l.max||1)}개`;return `<div class="drop-row ${eq?'equipment':''}"><span class="drop-icon">${itemSvg(itemAsset(l.id))}</span><span class="drop-name"><b>${esc(l.id)}</b><small>${eq?`장비 · ${esc(d?.rarity||'일반')}`:'제작 재료'} · ${qty}</small></span><span class="drop-rarity ${grade.replace(' ','-')}">${grade}</span><strong>${dropRate(l.chance)}</strong></div>`}).join('');modal(`<div class="sheet-head"><div><div class="section-kicker">${siteCode(site.id)}</div><h2>${esc(site.name)}${progress.boss_ready?'<span class="boss-flag"> BOSS</span>':''}</h2><p>권장 전투력 ${fmt(site.recommended_power)} · 승리 ${fmt(Math.min(500,progress.normal_wins||0))}/500</p></div><button class="close-btn" data-action="close">×</button></div>${chapterIntelPanel(site)}<section class="drop-panel"><header><div><b>획득 가능 아이템</b><small>전투 승리 1회 기준 기본 드롭률</small></div><em>${drops.length}종</em></header><div class="drop-list">${dropRows||'<div class="shop-empty">확인된 전리품이 없습니다.</div>'}</div><p>※ 약탈광·수집광·보스 보정 전 기본 확률입니다. 장비는 매우 낮은 확률로 드롭됩니다.</p></section>${ex.length?`<div class="brief-list">${ex.map(e=>{const party=partyOf(e);return `<div class="brief-item mission-live-row"><span class="mini-avatar">${party[0]?charSvg(monsterAsset(party[0].family)):''}</span><div><b>${party.length}인 박멸조 · ${esc(partyLabel(e))}</b><small>${esc(e.phase||'탐색')} · 승리 ${fmt(e.kills)} · 화물 ${lootCount(e)}개</small><div class="party-avatars">${party.map(mm=>`<span class="party-avatar">${charSvg(monsterAsset(mm.family),'party-sprite '+formClass(mm))}</span>`).join('')}</div><div class="battle-actions"><button class="primary-btn" data-action="watch" data-id="${e.id}">관전</button><button class="danger-btn" data-action="recall" data-id="${e.id}">복귀</button></div></div></div>`}).join('')}</div>`:''}<div class="party-select-head"><b>파티 편성</b><small>최대 4마리 · 경험치 ${selected.length?`1/${selected.length}`:'-'}</small></div><div class="party-select-list">${S.monsters.map(m=>{const busy=!!activeOf(m.id),sel=partyPick.includes(m.id);return `<button class="party-select-row ${sel?'selected':''} ${busy?'busy':''}" data-action="toggle-party" data-id="${m.id}" data-site="${site.id}" ${busy?'disabled':''}><span>${charSvg(monsterAsset(m.family))}</span><span><b>${esc(m.name)} · Lv.${m.level} · ${esc(m.growth_grade||'C')}</b><small>${formName(m)} · 전투력 ${fmt(power(m))}${busy?' · 다른 작전 참가 중':''}</small></span><em>${sel?'선택':busy?'출동중':'+'}</em></button>`}).join('')}</div><div class="party-launch"><div class="party-summary"><span>${selected.length}/4 선택</span><span>합산 전투력 ${fmt(sumPower)}</span><span>${progress.boss_ready?'보스전 대기':'일반 탐사'}</span></div><button class="primary-btn" data-action="deploy-party" data-site="${site.id}" ${!selected.length?'disabled':''}>${progress.boss_ready?'보스 박멸조 출정':'박멸조 출정'}</button></div>`,'mission-party-sheet') }


function chapterMeta(siteId){return ({
  mountain_village:{terrain:'침엽수림 · 목책 · 좁은 골목',weather:'산안개',objective:'민가 외곽을 훑으며 저항 세력과 숨겨진 보급품을 찾는다.',threat:'사냥꾼의 원거리 공격과 자경대장의 단단한 전열',copy:'산길과 목책 사이를 이동한다. 수색 중에는 보급품 흔적을 찾고, 인간 순찰대와 마주치면 즉시 교전한다.'},
  farm_road:{terrain:'논밭 · 마차길 · 곡물 창고',weather:'건조한 들바람',objective:'행상로와 창고 주변을 장악해 가죽과 운송 물자를 확보한다.',threat:'행상인 호위의 원거리 공격과 경비병의 방어 전열',copy:'넓은 농로와 창고 사이를 이동한다. 시야가 넓어 교전이 자주 발생하고 호위대가 빠르게 합류한다.'},
  border_outpost:{terrain:'석벽 · 감시탑 · 좁은 관문',weather:'횃불 경계',objective:'초소 경보망을 뚫고 병력과 왕국 보급품을 무력화한다.',threat:'석궁병의 높은 치명타와 기사 계열의 높은 방어력',copy:'감시탑과 석벽으로 둘러싸인 관문이다. 경보가 울리면 병사와 기사가 빠르게 전투에 합류한다.'}
}[siteId]||{terrain:'미확인 지형',weather:'불명',objective:'현장 정보를 확보한다.',threat:'확인되지 않은 인간 저항',copy:'현장 상황을 확인하며 탐색과 전투를 반복한다.'})}
function chapterIntelPanel(site){const meta=chapterMeta(site.id),enemies=site.enemy_names||[];return `<section class="chapter-intel ${site.id}"><header><div><small>CHAPTER INTEL</small><b>${esc(meta.terrain)}</b></div><span>${esc(meta.weather)}</span></header><p>${esc(meta.objective)}</p><div class="chapter-facts"><div><small>교전 주기</small><b>${fmt(site.battle_seconds)}초</b></div><div><small>승리 XP</small><b>${fmt(site.xp_per_kill)}</b></div><div><small>보스 전투력</small><b>${fmt(site.boss_power)}</b></div></div><div class="chapter-enemies"><small>출현 인간</small><div>${enemies.map(n=>`<span>${esc(n)}</span>`).join('')}</div></div><div class="chapter-boss"><small>BOSS</small><b>${esc(site.boss_name||'미확인')}</b><span>${fmt(site.boss_power)} 전투력</span></div><div class="chapter-threat"><b>주의</b><span>${esc(meta.threat)}</span></div></section>`}
function battleUi(siteId){const m=chapterMeta(siteId);return {alert:m.objective,copy:m.copy}}
function battleEventState(e){const ev=e?.event_state||{},latest=(e?.battle_log||[])[0]||null,battleNow=ev.type==='battle'&&latest?.type==='battle';return {kind:battleNow?'battle':'explore',event:ev,log:battleNow?latest:null,bs:e?.battle_state||{}}}
function battleSkillHtml(skills){if(!skills?.length)return '';return `<div class="battle-skill-banner">${skills.slice(0,4).map(s=>`<span><b>${esc(s.owner||'몬스터')}</b> ${esc(s.name||'고유 스킬')} <em>${s.round?`${fmt(s.round)}타`:'발동'}</em></span>`).join('')}</div>`}
function battleLogHtml(e,m,site){const rows=(e.battle_log||[]).slice(0,12);if(!rows.length)return '<div class="combat-log-empty">첫 현장 기록을 기다리는 중...</div>';return rows.map(x=>{if(x.type==='explore')return `<div class="combat-log-row explore"><header><b>${esc(x.phase||'탐색')}</b><small>현장 이벤트</small></header><p>${esc(x.event||'현장을 살피는 중')}</p>${Number(x.loot)>0?`<em>전리품 +${fmt(x.loot)}</em>`:''}</div>`;const enemy=esc(x.enemy||'용사'),role=esc(x.enemyRole||'인간'),skills=Array.isArray(x.skills)?x.skills:[],result=x.result==='win'?'승리':'패배';return `<div class="combat-log-row battle ${x.result||''}"><header><span><b>${enemy}</b><small>${role}${x.boss?' · BOSS':''}</small></span><strong>${result}</strong></header><div class="combat-metrics"><span>가한 피해 <b>${fmt(x.damageDealt||0)}</b></span><span>받은 피해 <b>${fmt(x.damageTaken||0)}</b></span><span>치명 <b>${fmt(x.crits||0)}</b></span><span>회피 <b>${fmt(x.dodges||0)}</b></span></div>${skills.length?`<div class="skill-proc-line">${skills.slice(0,4).map(s=>`<span><b>${esc(s.owner||'몬스터')}</b> · ${esc(s.name||'고유 스킬')}${s.round?` · ${fmt(s.round)}번째 공격`:''}</span>`).join('')}</div>`:''}${Number(x.loot)>0?`<footer>전리품 ${fmt(x.loot)}개 확보</footer>`:''}</div>`}).join('')}
function battlePartyHtml(e){const party=partyOf(e);return party.slice(0,4).map((m,i)=>`<div class="battle-party-unit" style="--party-index:${i}"><span>${charSvg(monsterAsset(m.family),'battle-sprite '+formClass(m))}</span><small>${esc(m.name)}</small></div>`).join('')}
function watchModal(expId){const e=S.expeditions.find(x=>x.id===expId);if(!e)return;const m=S.monsters.find(x=>x.id===e.monster_id),site=S.sites.find(x=>x.id===e.site_id),state=battleEventState(e),bs=state.bs,ui=battleUi(e.site_id),meta=chapterMeta(e.site_id),log=state.log,enemy=log?.enemy||bs.enemy||site?.enemy_names?.[0]||'용사',role=log?.enemyRole||bs.enemyRole||'인간',isBattle=state.kind==='battle',mhp=Number(bs.monsterHp||0),mmax=Number(bs.monsterMaxHp||monsterStats(m).hp),ehp=Number(bs.enemyHp||0),emax=Number(bs.enemyMaxHp||1),mpct=Math.max(0,Math.min(100,mmax?mhp/mmax*100:100)),epct=Math.max(0,Math.min(100,emax?ehp/emax*100:100)),skills=isBattle?(Array.isArray(log?.skills)?log.skills:Array.isArray(bs.skills)?bs.skills:[]):[];watchingExpeditionId=expId;lastBattleVisualKey=null;modal(`<div class="battle-report-head"><div><h2>${esc(site?.name||'현장')}</h2><small>${siteCode(e.site_id)} · 서버 실제 이벤트 · 탐사 ${fmt(e.exploration_count||0)}</small></div><button class="battle-report-close" data-action="close">×</button></div><div id="battleScene" class="battle-report-scene ${e.site_id} state-${state.kind} ${log?.boss?'boss':''} ${log?.result||''}"><div class="battle-scene-top"><span class="battle-opcode">${siteCode(e.site_id)}</span><span id="liveStateBadge" class="battle-server-badge">${isBattle?'COMBAT LIVE':esc(e.phase||'탐색')}</span></div><div class="chapter-atmosphere"><span>${esc(meta.terrain)}</span><small>${esc(meta.weather)}</small></div><div class="battle-stage"><div class="battle-party-side"><div id="livePartyCluster" class="battle-party-cluster">${battlePartyHtml(e)}</div><span class="battle-hp"><i id="liveMonsterHp" style="width:${mpct}%"></i></span><small id="liveMonsterHpText" class="hp-text">${isBattle?`${fmt(mhp||mmax)}/${fmt(mmax)}`:'이동/탐색 중'}</small></div><div class="battle-center-event"><div id="liveEncounterIcon" class="encounter-icon"><i class="encounter-pict ${isBattle?'combat':'explore'}"></i></div><b id="liveEncounterType">${isBattle?(log?.boss?'보스 교전':'교전 발생'):esc(e.phase||'탐색')}</b><small id="liveEncounterResult">${isBattle?(log?.result==='win'?'박멸 성공':'교전 패배'):'인간 흔적과 전리품을 탐색 중'}</small></div><div id="liveEnemyActor" class="battle-actor enemy-actor"><div id="liveEnemySprite" class="actor-frame">${charSvg(enemyAsset(enemy),'battle-sprite')}</div><span id="liveEnemyName" class="battle-name">${esc(enemy)} · ${esc(role)}</span><span class="battle-hp"><i id="liveEnemyHp" style="width:${epct}%"></i></span><small id="liveEnemyHpText" class="hp-text">${isBattle?`${fmt(ehp)}/${fmt(emax)}`:'접촉 없음'}</small></div></div><div id="liveCombatFloats" class="battle-float-stack"><span id="liveDamageFloat">${isBattle?`가한 피해 ${fmt(log?.damageDealt||bs.damageDealt||0)}`:'탐색 중'}</span><span id="liveTakenFloat">${isBattle?`받은 피해 ${fmt(log?.damageTaken||bs.damageTaken||0)}`:''}</span></div><div id="liveSkillProc">${battleSkillHtml(skills)}</div></div><div class="battle-report-body"><div id="liveAlert" class="battle-alert">${esc(e.event_state?.text||ui.alert)}</div><div class="battle-zone-copy"><b>현장 상황</b><span>${esc(ui.copy)}</span></div><div class="battle-summary detailed"><div><small>현재 단계</small><b id="livePhase">${esc(e.phase||'탐색')}</b></div><div><small>누적 박멸</small><b><span id="liveKills">${fmt(e.kills)}</span>명</b></div><div><small>회수 화물</small><b><span id="liveLoot">${lootCount(e)}</span>개</b></div><div><small>최근 치명타</small><b id="liveCrits">${isBattle?fmt(log?.crits||bs.crits||0):'-'}</b></div><div><small>최근 회피</small><b id="liveDodges">${isBattle?fmt(log?.dodges||bs.dodges||0):'-'}</b></div><div><small>적 역할</small><b id="liveEnemyRole">${isBattle?esc(role):'-'}</b></div></div><div class="combat-log-title"><b>서버 전투 기록</b><small>화면 연출과 동일 데이터</small></div><div id="liveLog" class="combat-log">${battleLogHtml(e,m,site)}</div></div><div class="battle-report-actions"><button class="retreat" data-action="recall" data-id="${e.id}">현장 철수</button></div>`,'battle-report-sheet battle-sync-sheet');syncWatchPanel()}

function itemModal(itemId){const inv=(S.inventory||[]).find(x=>x.item_id===itemId),d=itemDef(itemId),recipe=recipeForOutput(itemId);if(!inv)return;if(!d?.slot){if(recipe){modal(`<div class="sheet-head"><div><div class="section-kicker">FINISHED GOODS</div><h2>${esc(itemId)}</h2><p>완제품 · 보유 ${fmt(inv.qty)}개</p></div><button class="close-btn" data-action="close">×</button></div><div class="material-detail">${itemSvg(itemAsset(itemId))}<b>판매가 ${fmt(recipe.sale_gold)}G</b><p>상점 판매 ${secText(recipe.sell_seconds)} · 판매가와 동일한 기준으로 시간이 책정됩니다.</p><button class="primary-btn" data-action="shop">상점으로 이동</button></div>`);return}const used=(S.recipes||[]).filter(r=>Object.prototype.hasOwnProperty.call(r.inputs||{},itemId)),raw=rawSaleDef(itemId);modal(`<div class="sheet-head"><div><div class="section-kicker">CRAFT MATERIAL</div><h2>${esc(itemId)}</h2><p>제작 재료 · 보유 ${fmt(inv.qty)}개</p></div><button class="close-btn" data-action="close">×</button></div><div class="material-detail">${itemSvg(itemAsset(itemId))}<b>제작소 원재료</b><p>${used.length?`사용처: ${used.map(r=>esc(r.output_item)).join(' · ')}`:'현재 등록된 제작법에는 사용되지 않습니다.'}${raw?`<br>직접 판매 ${fmt(raw.sale_gold)}G · ${secText(raw.sell_seconds)} (가공품보다 저가)`:''}</p><div class="material-actions"><button class="primary-btn" data-action="workshop">제작소</button>${raw?'<button class="soft-btn" data-action="shop">상점</button>':''}</div></div>`);return}const bonus=[d.atk&&`공격 +${d.atk}`,d.def&&`방어 +${d.def}`,d.hp&&`HP +${d.hp}`,d.spd&&`속도 ${d.spd>0?'+':''}${d.spd}`,Number(d.crit)&&`치명 +${Math.round(Number(d.crit)*100)}%`,Number(d.evade)&&`회피 +${Math.round(Number(d.evade)*100)}%`,Number(d.human_damage)&&`인간 피해 +${Math.round(Number(d.human_damage)*100)}%`].filter(Boolean).join(' · ');modal(`<div class="sheet-head"><div><div class="section-kicker">EQUIPMENT</div><h2>${esc(itemId)}</h2><p>${esc(d.rarity)} · ${slotName(d.slot)} · 보유 ${fmt(inv.qty)}</p></div><button class="close-btn" data-action="close">×</button></div><div class="equipment-detail ${rarityClass(d.rarity)}"><div class="equipment-icon">${itemSvg(itemAsset(itemId))}</div><div><b>${esc(bonus||'특수 능력 없음')}</b><p>${esc(d.description||'')}</p></div></div><div class="equip-target-list">${S.monsters.map(m=>{const current=equippedFor(m.id).find(x=>x.slot===d.slot);return `<button data-action="equip" data-id="${m.id}" data-item="${esc(itemId)}"><span>${charSvg(monsterAsset(m.family),'mini-equip-char')}</span><span><b>${esc(m.name)}</b><small>${current?'현재 '+esc(current.item_id):slotName(d.slot)+' 비어 있음'}</small></span><em>장착</em></button>`}).join('')}</div>`,'item-detail-sheet-v10')}

function warehouseModal(){const total=inventoryTotal(),types=inventoryUsed();modal(`<div class="sheet-head"><div><div class="section-kicker">WAREHOUSE</div><h2>창고</h2><p>보유 ${fmt(total)}개 · ${fmt(types)}종</p></div><button class="close-btn" data-action="close">×</button></div><div class="warehouse-popup-note">전리품 수거는 <b>박멸 챕터 카드</b>에서 진행합니다.</div><div class="inventory-grid warehouse-popup-grid">${(S.inventory||[]).filter(x=>Number(x.qty||0)>0).length?(S.inventory||[]).filter(x=>Number(x.qty||0)>0).map(x=>{const d=itemDef(x.item_id),r=recipeForOutput(x.item_id);return `<button class="inventory-slot ${d?.slot?'equippable '+rarityClass(d.rarity):r?'crafted':''}" data-action="item" data-id="${esc(x.item_id)}"><div class="item-art small">${itemSvg(itemAsset(x.item_id))}</div><b>${esc(x.item_id)}</b><small>${fmt(x.qty)}개${d?.slot?' · '+slotName(d.slot):r?' · 판매품':''}</small></button>`}).join(''):'<div class="empty-state" style="grid-column:1/-1">창고가 비어 있습니다.</div>'}</div><div class="dim-close-hint">바깥 영역을 눌러 닫기</div>`,'warehouse-popup-sheet')}

function collectionDurationText(seconds){const n=Math.max(0,Math.floor(Number(seconds||0))),h=Math.floor(n/3600),m=Math.floor((n%3600)/60);return `${h}시간 ${m}분`}
function collectionResultModal(siteId,result){const site=(S?.sites||[]).find(x=>x.id===siteId),xpRows=Object.entries(result.xp||{}).filter(([,v])=>Number(v?.xp||0)>0),lootRows=Object.entries(result.loot||{}).filter(([,q])=>Number(q)>0);modal(`<div class="collection-result-head"><div><div class="section-kicker">BATTLE RESULT</div><h2>${collectionDurationText(result.durationSeconds)} 전투 결과</h2><p>${esc(site?.name||'박멸 지역')} · 전리품 수거 완료</p></div></div><section class="collection-xp"><header><b>몬스터 성장</b><small>실제 획득 XP</small></header>${xpRows.length?xpRows.map(([id,v])=>`<div class="collection-xp-row"><span>${charSvg(monsterAsset(v.family||'slime'),'collection-monster')}</span><b>${esc(v.name||'몬스터')}</b><strong>XP +${fmt(v.xp)}</strong></div>`).join(''):'<div class="collection-empty">이번 수거 구간에서 획득한 XP가 없습니다.</div>'}</section><section class="collection-loot"><header><b>획득 전리품</b><small>총 ${fmt(lootRows.reduce((a,[,q])=>a+Number(q||0),0))}개</small></header><div class="collection-loot-list">${lootRows.length?lootRows.map(([id,q])=>`<div class="collection-loot-row"><span>${itemSvg(itemAsset(id))}</span><b>${esc(id)}</b><strong>× ${fmt(q)}</strong></div>`).join(''):'<div class="collection-empty">획득한 전리품이 없습니다.</div>'}</div></section><div class="dim-close-hint">바깥 영역을 눌러 닫기</div>`,'collection-result-sheet')}
async function collectSiteLoot(siteId){if(busy)return;const before=siteExpeditions(siteId).filter(e=>lootCount(e)>0||expeditionPendingXp(e)>0);if(!before.length){toast('수거할 전리품이 없습니다.');return}const snapshotMonsters=new Map((S?.monsters||[]).map(m=>[m.id,{name:m.name,family:m.family}])),xp={},loot={};let durationSeconds=0;for(const e of before){const start=new Date(e.last_loot_collected_at||e.started_at||Date.now()).getTime(),end=e.active?Date.now():new Date(e.updated_at||Date.now()).getTime();if(Number.isFinite(start)&&Number.isFinite(end))durationSeconds=Math.max(durationSeconds,Math.max(0,(end-start)/1000));for(const [mid,amount] of Object.entries(e.pending_xp||{})){const n=Math.max(0,Number(amount||0));if(!n)continue;const meta=snapshotMonsters.get(mid)||{};if(!xp[mid])xp[mid]={xp:0,name:meta.name||'몬스터',family:meta.family||'slime'};xp[mid].xp+=n}}try{busy=true;for(const e of before){const d=await api('collect',{expeditionId:e.id});for(const [id,q] of Object.entries(d.collected||{}))loot[id]=(loot[id]||0)+Number(q||0)}render();collectionResultModal(siteId,{durationSeconds,xp,loot})}catch(err){toast(errorKo(err.message))}finally{busy=false}}

function menuModal(){const [rank,grade]=companyRank();modal(`<div class="sheet-head"><div><div class="section-kicker">COMPANY MENU</div><h2>경영 메뉴</h2><p>계정과 서버 상태를 확인합니다.</p></div><button class="close-btn" data-action="close">×</button></div><div class="account-panel"><img src="assets/brand-seal.svg" alt=""><div><b>${esc(S.account?.username||'사장')} 대표</b><small>${rank} · 법인등급 ${grade}<br>서버 세이브 정상 연결</small></div></div><div class="menu-actions"><button data-go="home">본부 현황</button><button data-go="monsters">몬스터 리스트</button><button data-go="hunt">박멸 작전</button><button data-action="warehouse">전리품 창고</button><button data-action="workshop">제작소</button><button data-action="shop">상점</button><button class="logout" data-action="logout">로그아웃</button></div>`,`menu-sheet`)}
function briefModal(){const active=(S.expeditions||[]).filter(e=>e.active),craft=activeCraftJobs().length,sell=activeSellJobs().length;modal(`<div class="sheet-head"><div><div class="section-kicker">CONTROL ROOM BRIEF</div><h2>상황실 브리핑</h2><p>현재 회사 운영 핵심 흐름입니다.</p></div><button class="close-btn" data-action="close">×</button></div><div class="brief-list"><div class="brief-item"><i></i><div><b>전투 골드 0G</b><small>전리품을 제작소에서 가공하고 상점에서 판매해야 골드를 얻습니다.</small></div></div><div class="brief-item"><i></i><div><b>출동 파티 ${active.length} · 제작 작업 ${craft}/${S.craftCapacity||5}</b><small>상점 작업 ${sell}/${S.shopCapacity||5} · 각 시설은 순차 대기열로 처리합니다.</small></div></div><div class="brief-item"><i></i><div><b>다음 지원자 ${candidateText()}</b><small>영입소 Lv.${S.player.tavern_level||1} · 3시간마다 ${recruitBatch()}명 도착</small></div></div><div class="brief-item"><i></i><div><b>회수 대기 화물 ${totalPending()}개</b><small>창고 ${inventoryUsed()}/${S.storageCapacity||40}</small></div></div></div>`)}


function syncWatchPanel(){if(!watchingExpeditionId||!S)return;const e=S.expeditions.find(x=>x.id===watchingExpeditionId);if(!e)return;const m=S.monsters.find(x=>x.id===e.monster_id),site=S.sites.find(x=>x.id===e.site_id),state=battleEventState(e),bs=state.bs,log=state.log,isBattle=state.kind==='battle',enemy=log?.enemy||bs.enemy||site?.enemy_names?.[0]||'용사',role=log?.enemyRole||bs.enemyRole||'인간',mhp=Number(bs.monsterHp||0),mmax=Number(bs.monsterMaxHp||monsterStats(m).hp),ehp=Number(bs.enemyHp||0),emax=Number(bs.enemyMaxHp||1),skills=isBattle?(Array.isArray(log?.skills)?log.skills:Array.isArray(bs.skills)?bs.skills:[]):[];const scene=$('#battleScene'),key=String(e.event_state?.t||bs.serverTick||log?.t||'');if(scene){scene.className=`battle-report-scene ${e.site_id} state-${state.kind} ${log?.boss?'boss':''} ${log?.result||''}`;if(key&&key!==lastBattleVisualKey){lastBattleVisualKey=key;scene.classList.remove('event-pulse','skill-pulse');void scene.offsetWidth;scene.classList.add('event-pulse');if(skills.length)scene.classList.add('skill-pulse')}}const text=(id,v)=>{const el=$(id);if(el)el.textContent=v};text('#liveKills',fmt(e.kills));text('#liveLoot',fmt(lootCount(e)));text('#liveEnemyName',isBattle?enemy+' · '+role:'접촉 없음');text('#liveAlert',e.event_state?.text||battleUi(e.site_id).alert);text('#livePhase',e.phase||'탐색');text('#liveStateBadge',isBattle?'COMBAT LIVE':e.phase||'탐색');text('#liveEncounterType',isBattle?(log?.boss?'보스 교전':'교전 발생'):e.phase||'탐색');text('#liveEncounterResult',isBattle?(log?.result==='win'?'박멸 성공':'교전 패배'):'인간 흔적과 전리품을 탐색 중');text('#liveDamageFloat',isBattle?`가한 피해 ${fmt(log?.damageDealt||bs.damageDealt||0)}`:'탐색 중');text('#liveTakenFloat',isBattle?`받은 피해 ${fmt(log?.damageTaken||bs.damageTaken||0)}`:'');text('#liveCrits',isBattle?fmt(log?.crits||bs.crits||0):'-');text('#liveDodges',isBattle?fmt(log?.dodges||bs.dodges||0):'-');text('#liveEnemyRole',isBattle?role:'-');const mh=$('#liveMonsterHp'),eh=$('#liveEnemyHp'),mht=$('#liveMonsterHpText'),eht=$('#liveEnemyHpText'),holder=$('#liveEnemySprite'),actor=$('#liveEnemyActor'),cluster=$('#livePartyCluster'),skill=$('#liveSkillProc'),logEl=$('#liveLog'),icon=$('#liveEncounterIcon .encounter-pict');if(icon)icon.className=`encounter-pict ${isBattle?'combat':'explore'}`;if(mh)mh.style.width=isBattle?`${Math.max(0,Math.min(100,mmax?mhp/mmax*100:100))}%`:'100%';if(eh)eh.style.width=isBattle?`${Math.max(0,Math.min(100,emax?ehp/emax*100:100))}%`:'0%';if(mht)mht.textContent=isBattle?`${fmt(mhp||mmax)}/${fmt(mmax)}`:'이동/탐색 중';if(eht)eht.textContent=isBattle?`${fmt(ehp)}/${fmt(emax)}`:'접촉 없음';if(actor)actor.classList.toggle('hidden-contact',!isBattle);if(holder&&isBattle){const u=holder.querySelector('use');if(u)u.setAttribute('href',`assets/characters.svg#${enemyAsset(enemy)}`)}if(cluster)cluster.innerHTML=battlePartyHtml(e);if(skill)skill.innerHTML=battleSkillHtml(skills);if(logEl&&m)logEl.innerHTML=battleLogHtml(e,m,site)}

function updateEconomyProgress(){document.querySelectorAll('[data-progress-start][data-progress-end]').forEach(el=>{const a=new Date(el.dataset.progressStart).getTime(),b=new Date(el.dataset.progressEnd).getTime(),n=Date.now(),waiting=n<a,pct=waiting?0:(!a||!b||b<=a?0:Math.max(0,Math.min(100,(n-a)/(b-a)*100))),fill=el.querySelector('.craft-progress-fill'),pc=el.querySelector('.job-percent'),left=el.querySelector('.job-left');if(fill)fill.style.width=pct+'%';if(pc)pc.textContent=waiting?'대기':Math.floor(pct)+'%';if(left)left.textContent=waiting?'대기 '+secText((a-n)/1000):secText(Math.max(0,(b-n)/1000))})}

async function refresh(){if(busy||!session||!S)return;try{await api('state');render()}catch(e){if(e.message==='unauthorized'){await sb.auth.signOut();showAuth()}else{if($('#briefLine'))$('#briefLine').textContent='서버 재연결 중...'}}}

$$('[data-auth-tab]').forEach(b=>b.addEventListener('click',()=>{$$('[data-auth-tab]').forEach(x=>x.classList.toggle('active',x===b));const signup=b.dataset.authTab==='signup';$('#loginForm').classList.toggle('hidden',signup);$('#signupForm').classList.toggle('hidden',!signup);authMsg('')}));
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const u=$('#loginId').value.trim().normalize('NFC'),p=$('#loginPw').value;if(!validKoreanId(u)){authMsg(errorKo('username_format'));return}if(!validPin(p)){authMsg(errorKo('password_format'));return}busy=true;authMsg('본부 연결 중...');try{const d=await loginAccount(u,p);await applySession(d.session);authMsg('');await enterGame()}catch(err){authMsg(errorKo(err.message))}finally{busy=false}});
$('#signupForm').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const u=$('#signupId').value.trim().normalize('NFC'),p=$('#signupPw').value,p2=$('#signupPw2').value;if(!validKoreanId(u)){authMsg(errorKo('username_format'));return}if(!validPin(p)){authMsg(errorKo('password_format'));return}if(p!==p2){authMsg('PIN 확인이 일치하지 않습니다.');return}busy=true;authMsg('사원 등록 중...');try{const d=await registerAccount(u,p);await applySession(d.session);authMsg('등록 완료.',true);await enterGame()}catch(err){authMsg(errorKo(err.message))}finally{busy=false}});

document.addEventListener('click',async e=>{if(e.target?.id==='modal'&&!e.target.classList.contains('hidden')){closeModal();return}const nav=e.target.closest('[data-screen]');if(nav){screen=nav.dataset.screen;closeModal();render();return}const go=e.target.closest('[data-go]');if(go){screen=go.dataset.go;closeModal();render();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='close'){closeModal();return}if(a==='menu'){menuModal();return}if(a==='brief'){briefModal();return}if(a==='candidates'){candidateModal();return}if(a==='dorm'){dormModal();return}if(a==='workshop'){workshopModal();return}if(a==='shop'){shopModal();return}if(a==='warehouse'){warehouseModal();return}if(a==='collect-site'){collectSiteLoot(b.dataset.site);return}if(a==='employee'){employeeModal(b.dataset.id);return}if(a==='evolution'){evolutionModal(b.dataset.id);return}if(a==='personality'){personalityModal(b.dataset.id);return}if(a==='mission'){missionModal(b.dataset.id);return}if(a==='watch'){watchModal(b.dataset.id);return}if(a==='item'){itemModal(b.dataset.id);return}if(a==='craft-setup'){craftQuantityModal(b.dataset.id);return}if(a==='sell-setup'){sellQuantityModal(b.dataset.id);return}if(a==='qty-dec'||a==='qty-inc'){const q=$('#qtySlider');if(q){q.value=String(Math.max(Number(q.min||1),Math.min(Number(q.max||1),Number(q.value||1)+(a==='qty-inc'?1:-1))));updateQuantitySheet()}return}if(a==='toggle-party'){const id=b.dataset.id,site=b.dataset.site;if(activeOf(id)){toast('이미 다른 작전에 참가 중입니다.');return}if(partyPick.includes(id))partyPick=partyPick.filter(x=>x!==id);else{if(partyPick.length>=4){toast('파티는 최대 4마리입니다.');return}partyPick.push(id)}missionModal(site,true);return}if(a==='logout'){if(busy)return;busy=true;try{await sb.auth.signOut();showAuth()}finally{busy=false}return}try{busy=true;if(a==='deploy-party'){const partyCount=partyPick.length;await api('deploy',{monsterIds:[...partyPick],siteId:b.dataset.site});closeModal();toast(`${partyCount}마리 박멸조 출정`);render()}else if(a==='recall'){await api('recall',{expeditionId:b.dataset.id});closeModal();toast('박멸조가 본부로 복귀했습니다.');render()}else if(a==='collect-all'){await api('collect');toast('대기 화물을 모두 수령했습니다.');render()}else if(a==='collect-one'){await api('collect',{expeditionId:b.dataset.id});toast('화물을 창고로 옮겼습니다.');render()}else if(a==='craft-confirm'){const qty=Number($('#qtySlider')?.value||1);await api('craft',{recipeId:b.dataset.id,quantity:qty});workshopModal();toast(`${fmt(qty)}개 제작 예약`)}else if(a==='sell-confirm'){const qty=Number($('#qtySlider')?.value||1);await api('sell',{itemId:b.dataset.id,quantity:qty});shopModal();toast(`${fmt(qty)}개 판매 예약`)}else if(a==='evolve-choice'){const mid=b.dataset.id,d=await api('evolve',{monsterId:mid,evolutionId:b.dataset.evolution});closeModal(true);render();toast(`${d.evolution?.formName||'전직'} 완료 · Lv.1`);employeeModal(mid)}else if(a==='hire'){await api('hire',{candidateId:b.dataset.id});candidateModal();toast('무료 영입 완료 · 숙소에 배치했습니다.')}else if(a==='reject'){await api('reject',{candidateId:b.dataset.id});candidateModal();toast('지원자를 돌려보냈습니다.')}else if(a==='equip'){await api('equip',{monsterId:b.dataset.id,itemId:b.dataset.item});closeModal();toast('장비를 장착했습니다.');render()}else if(a==='unequip'){await api('unequip',{monsterId:b.dataset.id,slot:b.dataset.slot});closeModal();toast('장비를 해제했습니다.');render()}else if(a==='upgrade'){await api('upgrade',{facility:b.dataset.id});closeModal();toast('시설 확장이 완료됐습니다.');render()}}catch(err){toast(errorKo(err.message))}finally{busy=false}});

document.addEventListener('input',e=>{if(e.target?.id==='qtySlider')updateQuantitySheet()});
sb.auth.onAuthStateChange((_event,newSession)=>{session=newSession});
setInterval(updateCandidateTimer,1000);
setInterval(updateEconomyProgress,1000);
setInterval(refresh,5000);
setInterval(syncWatchPanel,900);

(async()=>{try{const s=await currentSession();if(s)await enterGame();else showAuth()}catch(e){showAuth();authMsg('초기 서버 연결에 실패했습니다.')}})();
